<template>
  <section v-if="!framework||questions.length||opportunities.length" id="stock-decision-framework" class="decision-framework" aria-label="Five decision questions">
    <template v-if="framework">
      <header class="framework-heading"><div><h2>{{ questions.length===5?'Five questions before the investment decision':'Investment questions' }}</h2><p>The business, the price, the expectations and the ways this thesis can fail.</p></div><button class="stock-text-button" @click="$emit('research')">Read company research →</button></header>
      <p v-if="run.decision_framework_status!=='complete'" class="framework-note">Research synthesis · the final reviewer has not completed these answers yet.</p>
      <div class="question-grid">
        <article v-for="(question,index) in questions" :key="question.id" class="decision-question">
          <header><span class="question-number" aria-hidden="true">{{ index+1 }}</span><h3>{{ decisionQuestions[question.id] }}</h3></header>
          <div class="question-status"><span>{{ statusLabel(question.status) }}</span><span>{{ question.evidence_quality }} evidence</span></div>
          <p class="question-answer">{{ evidenceDisplayText(question.answer) }}</p>
          <p v-if="question.id==='market_expectations'&&question.expectation_basis!=='unknown'" class="expectation-basis">{{ expectationLabel(question.expectation_basis) }}. Simulated investors do not measure actual market expectations.</p>
          <div v-if="question.supporting_case?.length||question.opposing_case?.length" class="question-cases"><section v-for="side in caseSides(question)" :key="side"><h4>{{ side==='supporting_case'?'Supporting case':'Opposing case' }}</h4><ul v-if="question[side]?.length"><li v-for="(claim,i) in question[side]" :key="i"><span class="claim-basis">{{ basisLabel(claim.basis) }}</span><p>{{ evidenceDisplayText(claim.text) }}</p><StockSourceLinks :ids="claim.evidence_ids" :sources="run.dossier?.sources||[]"/></li></ul></section></div>
          <p v-if="question.id==='market_expectations'&&['observed_price_only','price_implied_hypothesis','unknown'].includes(question.expectation_basis)" class="framework-note">Verified aggregate analyst estimates and actual investor positioning are not established by quotes, issuer guidance or a broker article.</p>
          <details v-if="question.evidence_ids?.length" class="answer-evidence"><summary>Answer sources</summary><StockSourceLinks :ids="question.evidence_ids" :sources="run.dossier?.sources||[]"/></details>
        </article>
      </div>
      <section v-if="opportunities.length" class="business-opportunities"><header class="framework-heading"><div><h3>Business growth and opportunities</h3><p>What would have to happen for a business opportunity to affect the stock.</p></div></header><article v-for="opportunity in opportunities" :key="opportunity.id" class="opportunity"><h4>{{ opportunity.name }}</h4><span class="claim-basis">{{ opportunityStatus(opportunity.status) }}</span><details><summary>Capture, financial impact and failure conditions</summary><dl><div v-for="item in transmission.filter(item=>hasEvidenceValue(opportunity[item.key]))" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ evidenceDisplayText(opportunity[item.key]) }}</dd></div></dl><div v-if="opportunity.supporting_case?.length||opportunity.opposing_case?.length" class="question-cases"><section v-for="side in caseSides(opportunity)" :key="side"><h5>{{ side==='supporting_case'?'Supporting evidence':'Opposing evidence' }}</h5><div v-for="(claim,i) in opportunity[side]||[]" :key="i"><p>{{ basisLabel(claim.basis) }} · {{ evidenceDisplayText(claim.text) }}</p><StockSourceLinks :ids="claim.evidence_ids" :sources="run.dossier?.sources||[]"/></div></section></div><ul class="milestones"><li v-for="(milestone,i) in availableEvidenceItems(opportunity.milestones)" :key="i"><strong>{{ milestone.status }}<template v-if="hasEvidenceValue(milestone.date)"> · {{ milestone.date }}</template></strong><p>{{ evidenceDisplayText(milestone.condition) }}</p><StockSourceLinks :ids="milestone.evidence_ids" :sources="run.dossier?.sources||[]"/></li></ul><StockSourceLinks :ids="opportunity.evidence_ids" :sources="run.dossier?.sources||[]"/></details></article></section>
      <section v-if="thesisChecks.length" class="thesis-tests"><h3>Thesis checks and invalidation</h3><ul><li v-for="(check,index) in thesisChecks" :key="index"><strong>{{ check.status }}<template v-if="hasEvidenceValue(check.date)"> · {{ check.date }}</template></strong><p>{{ evidenceDisplayText(check.condition) }}</p><StockSourceLinks :ids="check.evidence_ids" :sources="run.dossier?.sources||[]"/></li></ul></section>
      <details v-if="coverage.length" class="collection-coverage"><summary>Business evidence collected</summary><p>Captured sources still require claim-level assessment; a downloaded financial report does not answer every business question.</p><ul><li v-for="topic in coverage" :key="topic.name"><strong>{{ topic.name }} · {{ topic.status==='sources_captured'?'Sources captured':topic.status==='context_captured'?'Supplied context · goal unverified':'No readable source' }}</strong><p>{{ topic.evidence_goal }}</p></li></ul></details>
      <p class="framework-note">Snapshot research · issuer claims, reported facts and hypotheses remain distinct · milestones are not monitored live.</p>
    </template>
    <div v-else-if="legacy" class="framework-legacy"><h2>Five decision questions</h2><p>This saved report predates the five-question framework. Reassess the company to collect focused business evidence and build the new answers. The original report stays preserved.</p><button v-if="finished" class="stock-secondary" :disabled="busy" @click="$emit('reassess')">Reassess with five questions</button></div>
    <div v-else class="framework-pending"><h2>Five decision questions</h2><p>Company-specific evidence is collected before the researchers answer these questions. Answers will appear after the evidence review.</p></div>
  </section>
</template>
<script setup>
import {computed} from 'vue'
import StockSourceLinks from './StockSourceLinks.vue'
import {availableEvidenceItems,hasEvidenceValue,evidenceDisplayText} from '../utils/availableEvidence.mjs'
import {decisionQuestions,frameworkFor,isLegacyFramework} from '../utils/stockFramework.mjs'
const props=defineProps({run:{type:Object,required:true},busy:Boolean})
defineEmits(['research','reassess'])
const framework=computed(()=>frameworkFor(props.run)),legacy=computed(()=>isLegacyFramework(props.run))
const questions=computed(()=>Object.keys(decisionQuestions).map(id=>framework.value?.questions?.find(question=>question.id===id)).filter(question=>question&&question.status!=='unknown'&&hasEvidenceValue(question.answer)))
const opportunities=computed(()=>availableEvidenceItems(framework.value?.opportunities))
const thesisChecks=computed(()=>availableEvidenceItems(framework.value?.thesis_tests))
const caseSides=value=>['supporting_case','opposing_case'].filter(side=>value[side]?.length)
const finished=computed(()=>['complete','complete_with_gaps'].includes(props.run.status))
const coverage=computed(()=>Object.entries(props.run.business_collection?.topic_coverage||{}).map(([name,value])=>({name,...value})).filter(topic=>['sources_captured','context_captured'].includes(topic.status)))
const statusLabel=status=>({supported:'Supported by captured evidence',partial:'Partial answer',unknown:'Not established'}[status]||status)
const basisLabel=basis=>({reported_fact:'Reported fact',issuer_claim:'Issuer claim',inference:'Interpretation',hypothesis:'Hypothesis'}[basis]||basis)
const expectationLabel=basis=>({observed_price_only:'Captured quotes and price history',price_implied_hypothesis:'Price-implied interpretation; not measured consensus',dated_analyst_estimates:'Captured dated analyst estimates',measured_positioning:'Captured timestamped positioning',unknown:'Market expectations are not established'}[basis]||basis)
const opportunityStatus=status=>({reported_driver:'Reported business driver',conditional_opportunity:'Conditional opportunity',hypothesis:'Hypothesis · capture not established',rejected:'Not supported'}[status]||status)
const transmission=[{key:'industry_change',label:'Industry or customer change'},{key:'company_capture',label:'How the company could capture it'},{key:'adoption_conditions',label:'Adoption and execution conditions'},{key:'financial_transmission',label:'Revenue, margins and cash'},{key:'price_expectations',label:'What this means relative to the price'},{key:'failure_condition',label:'What would prove it wrong'}]
</script>
<style scoped>
.decision-framework{margin:26px 0 34px;color:#26303b;overflow-wrap:anywhere}.framework-heading{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin-bottom:18px}.framework-heading h2,.framework-legacy h2,.framework-pending h2{font-size:25px;letter-spacing:-.65px;font-weight:500;margin:0 0 6px}.framework-heading p,.framework-pending p,.framework-legacy p{font-size:13px;line-height:1.7;color:#6a7583;margin:0}.framework-heading button{flex-shrink:0}.question-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.decision-question{border:1px solid #e2e7ed;border-radius:7px;padding:21px;background:white;min-width:0}.decision-question:last-child{grid-column:1/-1}.decision-question>header{display:flex;gap:12px;align-items:start}.question-number{width:23px;height:23px;border-radius:50%;background:#fff0e7;color:#af420f;font-size:11px;display:flex;align-items:center;justify-content:center;flex-shrink:0}.decision-question h3{font-size:18px;font-weight:500;line-height:1.45;margin:0;letter-spacing:-.35px}.question-status{display:flex;gap:15px;font-size:10px;color:#7a8593;margin:12px 0}.question-status>span:first-child{color:#a14a20}.question-answer{font-size:14px;line-height:1.75;color:#344150;margin:12px 0 16px}.question-cases{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding-top:14px;border-top:1px solid #edf0f4}.question-cases h4,.question-gaps h4{font-size:12px;margin:0 0 10px;font-weight:500;color:#45515f}.question-cases ul{list-style:none;padding:0;margin:0}.question-cases li{margin:0 0 13px}.question-cases p{font-size:12px;line-height:1.7;color:#66717f;margin:4px 0 7px}.claim-basis{font-size:10px;color:#927055}.case-empty{font-size:12px!important;line-height:1.7;color:#8993a0!important}.framework-citations{display:flex;flex-wrap:wrap;gap:5px 12px;font-size:10px;line-height:1.6;margin-top:6px}.framework-citations a{color:#a14a20;text-underline-offset:3px;overflow-wrap:anywhere;max-width:100%}.framework-citations span{color:#8791a0}.question-gaps{border-left:2px solid #e6baa3;padding:8px 11px;background:#fff9f5;margin-top:14px}.question-gaps ul{font-size:11px;line-height:1.7;margin:0;padding-left:15px;color:#816c5d}.framework-note,.expectation-basis{font-size:11px;line-height:1.75;color:#798494}.expectation-basis{background:#f7f8fa;padding:10px 12px;margin:13px 0}.answer-evidence,.collection-coverage{font-size:11px;color:#778392;margin-top:12px}.answer-evidence summary,.collection-coverage summary,.opportunity summary{cursor:pointer;text-underline-offset:3px}.business-opportunities,.thesis-tests{margin-top:25px;border-top:1px solid #e3e8ee;padding-top:22px}.business-opportunities h3,.thesis-tests h3{font-size:21px;letter-spacing:-.4px;font-weight:500;margin:0 0 7px}.opportunity{border-bottom:1px solid #edf0f4;padding:15px 0 18px}.opportunity h4{font-size:16px;font-weight:500;margin:0 0 4px}.opportunity details{margin-top:13px;font-size:12px;color:#647181;line-height:1.7}.opportunity dl{margin:17px 0}.opportunity dl>div{display:grid;grid-template-columns:180px 1fr;gap:18px;margin:12px 0}.opportunity dt{color:#475563;font-size:11px}.opportunity dd{margin:0;font-size:13px;color:#657281}.opportunity h5{font-size:11px;margin:0 0 8px;font-weight:500}.milestones,.opportunity-gaps,.thesis-tests ul,.collection-coverage ul{padding-left:18px;line-height:1.8;font-size:12px;color:#6f7c8b}.milestones strong,.thesis-tests strong{font-weight:500;font-size:11px;color:#687381}.milestones p,.thesis-tests p{margin:4px 0 14px;font-size:13px;line-height:1.7}.framework-legacy,.framework-pending{border-left:2px solid #e5b494;background:#fff9f5;padding:18px 20px}.framework-legacy button{margin-top:13px}.collection-coverage p{font-size:11px;line-height:1.7}.collection-coverage li{margin:13px 0}.collection-coverage strong{font-weight:500;color:#536273}.decision-framework a:focus-visible,.decision-framework button:focus-visible,.decision-framework summary:focus-visible{outline:2px solid #ad420f;outline-offset:4px}@media(max-width:850px){.question-grid{grid-template-columns:1fr}.decision-question:last-child{grid-column:auto}.question-cases{grid-template-columns:1fr;gap:11px}.framework-heading{align-items:start;flex-direction:column;gap:10px}.opportunity dl>div{grid-template-columns:1fr;gap:4px}.decision-question{padding:18px}.framework-heading h2{font-size:23px}.decision-question h3{font-size:17px}}
</style>
